# Published text of the 20 candidate seeds, transcribed from the Production DB (published versions).
C={}
def add(n,stem,ch): C['apphy2-mcq-%03d'%n]=(stem,ch)
add(1,"For an ideal gas at fixed volume, doubling absolute temperature makes pressure\n\nA. half\nB. unchanged\nC. double\nD. four times",[("A","half",0,"Assumes pressure is inversely proportional to temperature, as if it followed a Boyle's-law-style relation instead of the direct proportionality at fixed volume."),("B","unchanged",0,"Treats pressure as depending only on volume, forgetting that temperature is the variable being changed here."),("C","double",1,"P is proportional to T at fixed n and V"),("D","four times",0,"Assumes pressure scales with the square of temperature, mistakenly squaring the temperature ratio instead of applying direct proportionality.")])
add(2,"During an isothermal expansion of an ideal gas, its internal-energy change is\n\nA. positive\nB. negative\nC. zero\nD. equal to pressure",[("A","positive",0,"Assumes the gas gains internal energy simply because it expands and does work on its surroundings."),("B","negative",0,"Assumes the gas loses internal energy as it does work expanding, ignoring that the heat absorbed isothermally exactly offsets it."),("C","zero",1,"ideal-gas internal energy depends only on temperature"),("D","equal to pressure",0,"Confuses internal energy with pressure, treating the two as numerically interchangeable rather than recognizing internal energy depends only on temperature.")])
add(3,"Which of the following best explains why energy is spontaneously transferred from a hot object to a cold object?\n\nA. decreases total entropy\nB. increases total entropy\nC. violates energy conservation\nD. decreases the entropy of the cold object",[("A","decreases total entropy",0,"Reverses the direction required by the second law of thermodynamics for a spontaneous process."),("B","increases total entropy",1,"spontaneous heat transfer increases total entropy"),("C","violates energy conservation",0,"Confuses entropy increase with a violation of energy conservation, when heat flow conserves energy while still increasing entropy."),("D","decreases the entropy of the cold object",0,"Reverses the actual effect: heat flowing into the cold object increases its entropy (ΔS = Q/T_cold > 0), and this increase is what dominates the total-entropy change, not a decrease.")])
add(4,"The electric field direction at a point is the direction of force on\n\nA. a positive test charge\nB. a negative test charge\nC. any neutral object\nD. an electron only",[("A","a positive test charge",1,"field direction is defined using a positive test charge"),("B","a negative test charge",0,"Reverses the sign convention, treating the field as defined by the force on a negative test charge."),("C","any neutral object",0,"Forgets that a neutral object experiences no net electric force at all, so it cannot define a field direction."),("D","an electron only",0,"Overgeneralizes the negative-charge case to one specific particle instead of recognizing the convention uses a positive test charge.")])
add(5,"Moving a positive charge opposite a uniform electric field causes electric potential energy to\n\nA. decrease\nB. increase\nC. remain zero\nD. become mass",[("A","decrease",0,"Assumes moving against the field lowers potential energy, as if borrowing the sign convention from motion with a field (or gravity) rather than against it."),("B","increase",1,"potential rises opposite the field for positive charge"),("C","remain zero",0,"Assumes potential energy stays constant unless the charge moves along the field lines, ignoring the work done moving against the field."),("D","become mass",0,"Confuses energy-mass equivalence with ordinary electrostatic potential energy, a category error unrelated to this situation.")])
add(6,"Two identical positive point charges are separated. At their midpoint the electric field is\n\nA. zero\nB. toward the left charge\nC. toward the right charge\nD. infinite",[("A","zero",1,"The two charges are equal in magnitude and equidistant from the midpoint, so the electric field each produces there has equal magnitude. Because both charges are positive, each field points away from its own charge, meaning the two fields point in opposite directions at the midpoint. Equal-magnitude, opposite-direction vectors sum to zero, giving a net field of zero."),("B","toward the left charge",0,"Accounts only for the right charge's field at the midpoint (which points toward the left), ignoring the left charge's opposing contribution."),("C","toward the right charge",0,"Accounts only for the left charge's field at the midpoint (which points toward the right), ignoring the right charge's opposing contribution."),("D","infinite",0,"The midpoint is a finite distance from both charges, so each field is finite and the two fields cancel.")])
add(7,"Two resistors 3 Ω and 6 Ω in parallel have equivalent resistance\n\nA. 2 Ω\nB. 3 Ω\nC. 9 Ω\nD. 18 Ω",[("A","2 Ω",1,"reciprocal addition gives 2 ohms"),("B","3 Ω",0,"Picks the smaller resistor value directly, as if it alone set the parallel combination without performing the reciprocal sum."),("C","9 Ω",0,"Adds the resistances as if they were in series instead of combining them in parallel."),("D","18 Ω",0,"Stops partway through the product-over-sum shortcut, taking only the product of the two resistances without dividing by their sum.")])
add(8,"A 12 V battery drives 3 A through a resistor. Its resistance is\n\nA. 0.25 Ω\nB. 4 Ω\nC. 9 Ω\nD. 36 Ω",[("A","0.25 Ω",0,"Inverts the formula, computing I/V instead of V/I."),("B","4 Ω",1,"R=V/I"),("C","9 Ω",0,"Subtracts the given values (12-3=9) instead of dividing voltage by current."),("D","36 Ω",0,"Multiplies the given values (12x3=36) instead of dividing voltage by current.")])
add(9,"Immediately after an uncharged capacitor is connected through a resistor to a battery, the capacitor behaves approximately like\n\nA. an open circuit\nB. a wire\nC. a charged battery\nD. an inductor",[("A","an open circuit",0,"Describes the capacitor's long-time steady-state behavior, once it is fully charged and blocks current, rather than its initial state."),("B","a wire",1,"initial capacitor voltage is zero"),("C","a charged battery",0,"Assumes the capacitor starts fully charged and able to supply voltage, the opposite of its actual initial uncharged state."),("D","an inductor",0,"This confuses a capacitor with an inductor, which initially resists a sudden change in current.")])
add(19,"A photon has energy\n\nA. rest energy m0c²\nB. hf\nC. qV always\nD. p²/2m",[("A","rest energy m0c²",0,"This is the rest-energy expression for a massive particle, not the photon-energy relation."),("B","hf",1,"Planck's relation is E=hf"),("C","qV always",0,"Confuses photon energy with the energy gained by a charge accelerated through a potential difference, a formula from a different context."),("D","p²/2m",0,"Applies the non-relativistic kinetic energy formula for a massive particle to a massless photon.")])
add(21,"At fixed temperature and volume, doubling the number of ideal-gas molecules makes pressure\n\nA. half as large\nB. unchanged\nC. twice as large\nD. four times as large",[("A","half as large",0,"This applies an inverse relation between pressure and molecule count."),("B","unchanged",0,"This ignores the added molecular collisions with the container walls."),("C","twice as large",1,"From PV=NkT, pressure is directly proportional to molecule count at fixed V and T."),("D","four times as large",0,"This incorrectly squares the factor by which molecule count changes.")])
add(22,"Two rods have equal dimensions and temperature difference. Rod A has twice Rod B's thermal conductivity. The steady conduction rate through A is\n\nA. half as large\nB. the same\nC. twice as large\nD. four times as large",[("A","half as large",0,"This reverses the conductivity dependence, treating better conduction as slower transfer."),("B","the same",0,"This ignores the only property that differs between the rods."),("C","twice as large",1,"Conduction rate kAΔT/L is directly proportional to thermal conductivity k."),("D","four times as large",0,"This squares the conductivity factor even though the relation is linear.")])
add(23,"Two different ideal gases initially separated at the same temperature mix in an insulated container. The total entropy\n\nA. decreases\nB. stays constant\nC. increases\nD. becomes zero",[("A","decreases",0,"This reverses the second-law direction for spontaneous mixing."),("B","stays constant",0,"This treats insulation as preventing entropy change rather than preventing energy transfer."),("C","increases",1,"Spontaneous mixing increases the number of accessible arrangements and therefore total entropy."),("D","becomes zero",0,"This confuses an arbitrary entropy reference with the positive mixing change.")])
add(24,"Identical isolated conducting spheres carry charges +6Q and 0. They touch and separate. After separating, the two spheres' charges are\n\nA. +6Q and 0\nB. +3Q and +3Q\nC. +6Q and +6Q\nD. 0 and 0",[("A","+6Q and 0",0,"This assumes no charge redistribution occurs between identical conductors in contact, but touching connects the spheres electrically, letting charge flow until both reach the same potential."),("B","+3Q and +3Q",1,"Total charge +6Q is conserved. Since the spheres are identical (same capacitance), touching brings them to equal potential, which requires equal final charge: +3Q each."),("C","+6Q and +6Q",0,"This duplicates the original charge instead of redistributing it, violating conservation of charge (total would become +12Q)."),("D","0 and 0",0,"This assumes complete neutralization, but there is no negative charge present to cancel the +6Q -- conservation of charge requires the total to remain +6Q.")])
add(25,"At a point where electric potential is zero, the electric field\n\nA. must be zero\nB. must be constant nearby\nC. may be nonzero\nD. must point toward that point",[("A","must be zero",0,"This confuses a potential reference value with zero potential change."),("B","must be constant nearby",0,"Zero potential at one point does not imply that potential is constant in the surrounding region."),("C","may be nonzero",1,"Potential value can be zero while its spatial change, and hence electric field, is nonzero."),("D","must point toward that point",0,"Electric-field direction depends on the spatial decrease of potential, not on whether the potential value at one point is zero.")])
add(26,"An electron accelerated from rest through a potential difference magnitude ΔV gains kinetic energy equal to:",[("A","eΔV",1,"The kinetic-energy gain magnitude is |qΔV|=eΔV, by the work-energy theorem applied to the electric force."),("B","(1/2)eΔV",0,"This incorrectly carries the 1/2 from the kinetic-energy expression (1/2)mv² into the answer; the work-energy theorem already gives the full eΔV as the energy gained, without an extra factor of 1/2."),("C","2eΔV",0,"This introduces an unnecessary factor of two that does not appear anywhere in the work-energy relation W=qΔV."),("D","-eΔV",0,"This assigns a negative kinetic-energy gain by carrying the electron's negative charge sign into the answer, but kinetic energy gained by an accelerated charge is a positive quantity; the relevant quantity is the magnitude |qΔV|=eΔV, not the signed product.")])
add(27,"The voltage across a fixed resistor is doubled. Its power dissipation becomes\n\nA. half\nB. twice\nC. four times\nD. unchanged",[("A","half",0,"This applies an inverse voltage dependence not present in resistor power."),("B","twice",0,"This uses P proportional to V and misses the square."),("C","four times",1,"For fixed R, P=V²/R, so doubling voltage multiplies power by four."),("D","unchanged",0,"This ignores the increased current and voltage across the resistor.")])
add(28,"Traversing an ideal battery from its negative terminal to its positive terminal in a loop equation contributes\n\nA. +emf\nB. -emf\nC. zero\nD. depends on the current direction",[("A","+emf",1,"Moving from negative to positive terminal is a potential rise of +emf."),("B","-emf",0,"This assigns the sign for traversing from positive to negative terminal."),("C","zero",0,"This ignores the battery's nonzero potential change."),("D","depends on the current direction",0,"The battery term's sign is determined by the direction in which the loop is traversed, not by current direction.")])
add(29,"Currents 2.0 A and 3.5 A enter a junction. If one current leaves, its magnitude is\n\nA. 1.5 A\nB. 2.75 A\nC. 5.5 A\nD. 3.5 A",[("A","1.5 A",0,"This subtracts entering currents rather than summing them."),("B","2.75 A",0,"This averages the entering currents, which does not conserve charge flow."),("C","5.5 A",1,"Charge conservation requires outgoing current 2.0+3.5=5.5 A."),("D","3.5 A",0,"This uses only the larger incoming current and ignores the additional 2.0 A entering the junction.")])
add(30,"A capacitor in series with a resistor has been connected to a DC battery for a very long time. The circuit current is\n\nA. battery voltage divided by R\nB. zero\nC. infinite\nD. set only by C",[("A","battery voltage divided by R",0,"This describes the instant just after connecting an initially uncharged capacitor."),("B","zero",1,"At long time the capacitor is fully charged and behaves as an open circuit, so current is zero."),("C","infinite",0,"This treats the capacitor as a zero-resistance short at steady state."),("D","set only by C",0,"This ignores that capacitance affects the transient time, not the final DC current.")])
